// Validar payload mínimo y normalizar.
// Esperamos: { email, nombre?, fuente?, utm_campaign?, utm_source? }
const body = $input.item.json.body || $input.item.json;

if (!body.email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(body.email)) {
  throw new Error('Email inválido o ausente');
}

return {
  email: body.email.toLowerCase().trim(),
  nombre: (body.nombre || '').trim() || null,
  fuente: body.fuente || 'directo',
  utm_campaign: body.utm_campaign || null,
  utm_source: body.utm_source || null,
  pain_point: body.pain_point || null,
  fecha_captura: new Date().toISOString().split('T')[0]
};

